#' Friedman M Test
#'
#' 
#' @param data .
#' @param x .
#' @param a .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$h0} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$q} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$qt} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$qt$asDF}
#'
#' \code{as.data.frame(results$qt)}
#'
#' @export
FriedmanMTest <- function(
    data,
    x,
    a = "0.05") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("FriedmanMTest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL))


    options <- FriedmanMTestOptions$new(
        x = x,
        a = a)

    analysis <- FriedmanMTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

